def gh_deploy_key_setup(key_path, dry_run=False, path='.'):
    "Upload the SSH private key at `key_path` as the `DEPLOY_KEY` secret that deploy jobs use."
    key = Path(key_path).read_text()
    gh_secret('DEPLOY_KEY', key, dry_run=dry_run, path=path)
    if not dry_run: print(f'DEPLOY_KEY set from {key_path}')

# %% ../nbs/00_core.ipynb #ebfd551afe6333bc
def _git_branch(path='.'):
    "Return the current branch, or `main` when it cannot be read."
    try: return gateway().out(path, 'branch', '--show-current', check=False).strip() or 'main'
    except GitError: return 'main'

def _resolve_gh_repo_input(ref=None, path='.'):
    "Normalize to (owner, repo). Accepts 'owner/repo', GitHub URL, or local path."
    if ref is None: return _get_repo_slug(path)
    if '/' in ref and 'github.com' not in ref: return tuple(ref.split('/', 1))
    m = re.search(r'github\.com[:/]([^/]+)/([^/]+?)(?:\.git)?$', ref)
    if m: return m.group(1), m.group(2)
    raise ValueError(f'Cannot parse owner/repo from: {ref}')

# %% ../nbs/00_core.ipynb #301398c4
def _pr_api(path):
    "Return `(api, owner, name)` for this repository, or raise `GitError` when it has no GitHub remote."
    try: owner, name, api = gh_api(token=gh_token(), path=path)
    except ValueError as e: raise GitError(f'this repository has no GitHub remote ({e})') from e
    return api, owner, name

def _checks(api, sha):
    "Check runs for one commit, as counts and the names that are not green."
    runs, page = [], 1
    try:
        while True:
            res = api.checks.list_for_ref(sha, per_page=100, page=page)
            runs += res['check_runs']
            if not res['check_runs'] or len(runs) >= res['total_count']: break
            page += 1
    except Exception: return {}
    bad = [r['name'] for r in runs if r['conclusion'] not in (None, 'success', 'neutral', 'skipped')]
    return {'total': len(runs), 'failing': bad[:12],
            'pending': sum(1 for r in runs if r['status'] != 'completed')}

@flexicache(time_policy(60), maxsize=32)
def pr_context(path, branch):
    "Return the open pull request for `branch`, how far its base has moved, and its checks, or `pr=None` with the reason in `note`."
    try:
        api, owner, name = _pr_api(path)
        pr = first(api.pulls.list(head=f'{owner}:{branch}', state='open', per_page=5))
        if pr is None: return {'pr': None, 'note': f'no open pull request for {branch}'}
        cmp = api.repos.compare_commits(f"{pr['base']['ref']}...{branch}")
        return {'note': '', 'pr': {
            'number': pr['number'], 'title': pr['title'], 'url': pr['html_url'],
            'base': pr['base']['ref'], 'draft': bool(pr.get('draft')),
            'mergeable_state': pr.get('mergeable_state') or '',
            'behind_base': cmp['behind_by'], 'ahead_of_base': cmp['ahead_by'],
            'checks': _checks(api, pr['head']['sha'])}}
    except Exception as e:
        return {'pr': None, 'note': f'GitHub: {e}'}

# %% ../nbs/00_core.ipynb #d0a93de85b941902
def gh_init(name, host, domain, env='prod', branch=None, srv_path='/srv/app',
            health_path='/health', test_cmd=None, env_schema=None,
            hooks=None, lfs=None, workflows=None, workflow_preset=None,
            deploy_cmd=None, path='.'):
    "Write a new `.gheasy/config.json` with one environment, replacing any config already there."
    branch = branch or _git_branch(path)
    cfg = GheasyConfig(app=name, health_path=health_path, test_cmd=test_cmd, env_schema=env_schema or {},
        hooks=hooks or {}, lfs=lfs or [], workflows=workflows or {}, workflow_preset=workflow_preset,deploy_cmd=deploy_cmd)
    cfg.add_env(env, host, domain, branch=branch, srv_path=srv_path)
    cfg.save(path)
    print(f'Config written to {cfg_path(path)}')
    return cfg_path(path)

# %% ../nbs/00_core.ipynb #79f8b906fe103403
def gh_add_env(env, host, domain, branch=None, srv_path='/srv/app', path='.'):
    "Add or replace the environment `env` in the config and rewrite the local workflow file."
    cfg = GheasyConfig.load(path)
    cfg.add_env(env, host, domain, branch=branch or _git_branch(path), srv_path=srv_path)
    cfg.save(path)
    wf_path = Path(path) / '.github' / 'workflows' / 'gheasy.yml'
    wf_path.parent.mkdir(parents=True, exist_ok=True)
    wf_path.write_text(mk_workflow(cfg))
    print(f'Added env {env!r}. Run gh_workflow() to push to GitHub.')

def gh_add_job(name, job, path='.'):
    "Store a custom GitHub Actions job dict in the config for the next `gh_workflow`."
    cfg = GheasyConfig.load(path)
    cfg.add_job(name, job).save(path)
    print(f'Added job {name!r}. Run gh_workflow() to push.')

def gh_workflow(token=None, path='.'):
    "Write `.github/workflows/gheasy.yml` from the config, and with a token also commit it to GitHub."
    cfg = GheasyConfig.load(path)
    wf_str = mk_workflow(cfg)
    wf_path = Path(path) / '.github' / 'workflows' / 'gheasy.yml'
    wf_path.parent.mkdir(parents=True, exist_ok=True)
    wf_path.write_text(wf_str)
    print(f'Workflow written to {wf_path}')
    if token:
        import base64
        owner, repo, api = gh_api(token, path)
        content = base64.b64encode(wf_str.encode()).decode()
        try:
            existing = api.repos.get_content(path='.github/workflows/gheasy.yml')
            api.repos.create_or_update_file_contents(
                path='.github/workflows/gheasy.yml',
                message='chore: update gheasy workflow',
                content=content, sha=existing.sha)
        except Exception:
            api.repos.create_or_update_file_contents(
                path='.github/workflows/gheasy.yml',
                message='chore: add gheasy workflow',
                content=content)
        print('Workflow uploaded to GitHub.')

def gh_status(path='.'):
    "Print a table of the deploys recorded in the config."
    if not cfg_path(path).exists():
        print('No .gheasy/config.json found.')
        return
    cfg = GheasyConfig.load(path)
    if not cfg.deploys:
        print('No deploys recorded yet.')
        return
    print(f'{"Env":<12} {"Domain":<30} {"Version":<10} {"Deployed At":<25} {"Status"}')
    print('-' * 90)
    for env_name, d in cfg.deploys.items():
        env_cfg = cfg.envs.get(env_name, EnvConfig(host='?', domain='?'))
        print(f'{env_name:<12} {env_cfg.domain:<30} {d.get("version","?")[:8]:<10} '
              f'{d.get("deployed_at","?"):<25} {d.get("status","?")}')

def gh_ship(token=None, path='.'):
    "Write the workflow (and upload it when given a token), then print the deploy table."
    gh_workflow(token=token, path=path)
    gh_status(path=path)

def gh_record_deploy(env, sha, path='.'):
    "Record that commit `sha` is deployed to `env`, with the time; CI calls this after a successful deploy."
    cfg = GheasyConfig.load(path)
    cfg.deploys[env] = {
        'version': sha,
        'deployed_at': datetime.now(timezone.utc).isoformat(),
        'status': 'active',
    }
    cfg.save(path)

