@dataclass
class GheasyRepo:
    "A GitHub repository and a local path, with methods that run the `gh_*` functions on them."
    ref: str = None
    token: str = None
    path: str = '.'

    def __post_init__(self):
        if self.ref: self._owner, self._repo = _resolve_gh_repo_input(self.ref, self.path)
        else: self._owner, self._repo = None, None

    @property
    def full_name(self): return f'{self._owner}/{self._repo}' if self._owner and self._repo else None

    def check(self, remote=True, local=True, verbose=True):
        return gh_check(self._owner, self._repo, self.token, self.path, remote, local, verbose)

    def apply(self, findings=None, dry_run=False, confirm=False):
        if findings is None: findings = self.check(verbose=False)
        return gh_apply(findings, dry_run=dry_run, confirm=confirm)

    def create(self, private=True, description='', auto_init=False):
        "Create the repo under its owner: an org through `create_in_org`, else the signed-in user."
        api = GhApi(token=self.token or gh_token(), sync=True)
        owner = self._owner or api.users.get_authenticated().login
        try: api.repos.get(owner=owner, repo=self._repo); return None
        except HTTP404NotFoundError: pass
        kw = dict(name=self._repo, private=private, description=description, auto_init=auto_init)
        if self._owner and self._owner.lower() != api.users.get_authenticated().login.lower(): return api.repos.create_in_org(org=self._owner, **kw)
        return api.repos.create_for_authenticated_user(**kw)

    @classmethod
    def new(cls, ref, template='nbdev', private=True, description='',
            token=None, parent_dir='.', topics=None, workflows=None, python=DEFAULT_PYTHON):
        "Create a GitHub repository, clone it, scaffold and configure the project, and push the first commit."
        owner, repo = _resolve_gh_repo_input(ref)
        inst = cls(ref=ref, token=token or gh_token())
        inst.create(private=private, description=description)
        local_path = Path(parent_dir) / repo
        if not (local_path / '.git').exists(): sp.run(['git', 'clone', f'https://github.com/{owner}/{repo}', str(local_path)], check=True, stdin=sp.DEVNULL)
        else: print(f'Repo already cloned at {local_path}, skipping clone.')
        sp.run(['uv', 'python', 'pin', python], cwd=local_path, check=True, stdin=sp.DEVNULL)
        if template == 'nbdev': sp.run(['uv', 'run', 'nbdev-new'], cwd=local_path, check=True, stdin=sp.DEVNULL)
        gh_pyproject_to_hatchling(path=local_path)
        gh_lfs(persist=True, path=local_path)
        gh_githooks_pre_commit(path=local_path)
        if workflows: gh_init(repo, '', '', workflows=workflows, path=local_path)
        if workflows: gh_workflow(path=local_path)
        sp.run(['git', 'add', '-A'], cwd=local_path, check=True, stdin=sp.DEVNULL)
        sp.run(['git', 'commit', '-m', 'chore: gheasy init'], cwd=local_path, check=True, stdin=sp.DEVNULL)
        sp.run(['git', 'push', '-u', 'origin', 'HEAD'], cwd=local_path, check=True, stdin=sp.DEVNULL)
        if topics: gh_topics(topics, token=inst.token, path=local_path)
        return cls(ref=ref, token=inst.token, path=str(local_path))

